// @name Reversi
// @background #f2efe7
// @refresh 3600
// Reversi (Othello) for a touch screen: tap a square to place a disc and turn
// every line of the other color it closes in. Play the computer or a friend.
// The game in progress is kept on the frame.
import { replay, bestMove, counts, isLegal, toCell } from './logic'
import { highContrast, canvasOf, Button, OptionsPage, Title } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f2efe7] text-[#1f2a2e]',
    muted: 'text-[#5f6b66]',
    button: 'bg-[#e2ddd0] text-[#1f2a2e] active:bg-[#d3ccba]',
    primary: 'bg-[#2e5e4e] text-white active:bg-[#3a735f]',
    on: 'bg-[#2e5e4e] text-white',
    off: 'bg-[#e2ddd0] text-[#1f2a2e]',
    board: '#2e5e4e',
    line: '#1f453a',
    edge: '#1a3a31',
    discs: ['', '#1c1f22', '#f7f5ef'],
    discEdge: ['', '#000000', '#bdb7aa'],
    hint: '#173328',
    last: '#d9734e',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    board: '#ffffff',
    line: '#000000',
    edge: '#000000',
    discs: ['', '#000000', '#ffffff'],
    discEdge: ['', '#000000', '#000000'],
    hint: '#000000',
    last: '',
  },
}
const NAMES = ['', 'Black', 'White']

const OPTIONS = [
  { field: 'opponent', label: 'Opponent', options: [['computer', 'Computer'], ['human', 'Two players']] },
  { field: 'level', label: 'Computer level', options: [['easy', 'Easy'], ['medium', 'Medium'], ['hard', 'Hard']] },
  { field: 'side', label: 'You play', options: [['black', 'Black (first)'], ['white', 'White']] },
  { field: 'hints', label: 'Legal moves', options: [['show', 'Show'], ['hide', 'Hide']] },
]

const settingsOf = (app) => ({
  vsComputer: (app.state.opponent || 'computer') !== 'human',
  level: app.state.level || 'medium',
  human: app.state.side === 'white' ? 2 : 1,
  hints: app.state.hints !== 'hide',
})

// The game in progress, kept in the scene's private `game` field: the squares
// played, 0..63. The board is rebuilt from them, so undo drops the last ones.
type Game = { moves: number[] }
const loadGame = (app): Game => {
  const g = app.state.game
  return g && Array.isArray(g.moves) ? g : { moves: [] }
}
const save = (game: Game) => frameos.setState('game', game)

// The computer's moves while it is its turn (twice or more when you have to
// pass).
const settle = (app, game: Game): Game => {
  const { vsComputer, level, human } = settingsOf(app)
  if (!vsComputer) return game
  let state = replay(game.moves)
  let moves = game.moves
  while (!state.result && state.toMove !== human) {
    const square = bestMove(state.board, state.toMove, level, Math.random)
    if (square < 0) break
    moves = [...moves, square]
    state = replay(moves)
  }
  return moves === game.moves ? game : { moves }
}

const place = (app, square: number) => {
  const game = loadGame(app)
  const state = replay(game.moves)
  const { vsComputer, human } = settingsOf(app)
  if (state.result || (vsComputer && state.toMove !== human)) return
  if (!isLegal(state.board, toCell(square), state.toMove)) return
  save(settle(app, { moves: [...game.moves, square] }))
}

// Back to your last turn against the computer, one move with two players.
const undo = (app) => {
  const game = loadGame(app)
  const { vsComputer, human } = settingsOf(app)
  const moves = game.moves.slice()
  if (!moves.length) return
  moves.pop()
  if (vsComputer) {
    while (moves.length && replay(moves).toMove !== human) moves.pop()
  }
  save({ moves })
}

const restart = (app) => {
  save(settle(app, { moves: [] }))
  frameos.remember('page', null)
}

// Buttons on frames without a touch screen: back is undo, forward a new game
// once this one is over. On a keyboard U undoes and N starts again.
export function onEvent(app, context) {
  const event = context.event
  if (event === 'back') undo(app)
  else if (event === 'forward') {
    if (!replay(loadGame(app).moves).result) return false
    restart(app)
  } else if (event === 'keyDown') {
    const p = context.payload || {}
    const key = String(p.key || '').toLowerCase()
    if (p.ctrl || p.alt || p.meta) return false
    if (key === 'u' || key === 'backspace') undo(app)
    else if (key === 'n') restart(app)
    else return false
  } else return false
  return true
}

// The board, 100 units a square: the discs, the moves the player to move
// may make (small dots) and a mark on the last disc played.
const Board = ({ t, state, last, hints, size }) => {
  const parts = []
  for (let i = 1; i < 8; i++) {
    parts.push(<line x1={i * 100} y1={0} x2={i * 100} y2={800} stroke={t.line} strokeWidth={4} />)
    parts.push(<line x1={0} y1={i * 100} x2={800} y2={i * 100} stroke={t.line} strokeWidth={4} />)
  }
  for (const [x, y] of [[200, 200], [600, 200], [200, 600], [600, 600]]) {
    parts.push(<circle cx={x} cy={y} r={9} fill={t.line} />)
  }
  for (let square = 0; square < 64; square++) {
    const cx = (square % 8) * 100 + 50
    const cy = Math.floor(square / 8) * 100 + 50
    const cell = toCell(square)
    const who = state.board[cell]
    if (who === 1 || who === 2) {
      parts.push(<circle cx={cx} cy={cy} r={40} fill={t.discs[who]} stroke={t.discEdge[who]} strokeWidth={who === 2 ? 6 : 3} />)
      if (square === last) {
        parts.push(t.last
          ? <circle cx={cx} cy={cy} r={11} fill={t.last} />
          : <rect x={cx - 10} y={cy - 10} width={20} height={20} fill={t.discs[3 - who]} />)
      }
    } else if (hints && !state.result && isLegal(state.board, cell, state.toMove)) {
      parts.push(<circle cx={cx} cy={cy} r={13} fill="none" stroke={t.hint} strokeWidth={5} />)
    }
  }
  return (
    <svg viewBox="-10 -10 820 820" width={size} height={size}>
      <rect x={-8} y={-8} width={816} height={816} rx={14} fill={t.board} stroke={t.edge} strokeWidth={6} />
      {parts}
    </svg>
  )
}

const Disc = ({ t, who, size }) => (
  <svg viewBox="0 0 40 40" className={`w-[${size}px] h-[${size}px]`}>
    <circle cx={20} cy={20} r={16} fill={t.discs[who]} stroke={who === 2 ? '#000000' : t.discEdge[who]} strokeWidth={who === 2 ? 3 : 2} />
  </svg>
)

export function get(app, context) {
  const ui = canvasOf(app, context)
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows = OPTIONS.filter((row) => settings.vsComputer || (row.field !== 'level' && row.field !== 'side')).map((row) => ({
      ...row,
      value: app.state[row.field] || row.options[0][0],
    }))
    return <OptionsPage ui={ui} t={t} title="Reversi" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  // The computer opens when you play white, or moves after a settings change.
  let game = loadGame(app)
  const settled = settle(app, game)
  if (settled !== game) {
    game = settled
    save(game)
  }
  const state = replay(game.moves)
  const last = state.played ? game.moves[state.played - 1] : -1
  const { black, white } = counts(state.board)
  const { vsComputer, human } = settings
  const name = (who: number) => (vsComputer ? (who === human ? 'You' : 'The computer') : NAMES[who])
  let status
  if (state.result === 3) status = `A draw, ${black} all`
  else if (state.result) {
    const hi = Math.max(black, white)
    const lo = Math.min(black, white)
    status = vsComputer ? (state.result === human ? `You win ${hi} to ${lo}!` : `The computer wins ${hi} to ${lo}`) : `${NAMES[state.result]} wins ${hi} to ${lo}!`
  } else status = vsComputer ? 'Your turn' : `${NAMES[state.toMove]} to play`
  const note = !state.result && state.passed ? `${name(state.passed)} had no move` : ''

  // Side by side or stacked, whichever gives the bigger board.
  const sideW = Math.round(Math.max(ui.W * 0.27, ui.text * 9))
  const sideSize = Math.min(ui.W - sideW - ui.pad * 3, ui.H - ui.pad * 2)
  const stackSize = Math.min(ui.W - ui.pad * 2, ui.H - ui.pad * 2 - ui.gap * 2 - ui.button * 2)
  const side = sideSize >= stackSize
  const size = Math.floor(side ? sideSize : stackSize)

  const board = (
    <div className={`w-[${size}px] h-[${size}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor(((e.localX / e.width) * 820 - 10) / 100)
        const row = Math.floor(((e.localY / e.height) * 820 - 10) / 100)
        if (col >= 0 && col < 8 && row >= 0 && row < 8) place(app, row * 8 + col)
      }}>
      <Board t={t} state={state} last={last} hints={settings.hints} size={size} />
    </div>
  )
  const discSize = Math.round(ui.big * 1.15)
  const tally = (
    <div className={`flex items-center gap-[${ui.gap}px] text-[${ui.big}px] font-bold`}>
      <Disc t={t} who={1} size={discSize} />
      <span>{black}</span>
      <span className="w-[8px]" />
      <Disc t={t} who={2} size={discSize} />
      <span>{white}</span>
    </div>
  )
  const statusBlock = (
    <div className="flex flex-col">
      <div className={`flex items-center gap-[${Math.round(ui.gap * 0.8)}px]`}>
        {state.result === 3 ? null : <Disc t={t} who={state.result || state.toMove} size={Math.round(ui.text * 1.2)} />}
        <span className={`text-[${ui.text}px] font-semibold leading-tight`}>{status}</span>
      </div>
      {note ? <span className={`text-[${ui.small}px] ${t.muted}`}>{note}</span> : null}
    </div>
  )
  const buttons = [
    <Button ui={ui} grow={!side} className={t.button} onClick={() => undo(app)}>Undo</Button>,
    <Button ui={ui} grow={!side} className={state.result ? t.primary : t.button} onClick={() => restart(app)}>New game</Button>,
    <Button ui={ui} grow={!side} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>,
  ]

  if (side) {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        {board}
        <div className={`flex-1 h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={ui.W - ui.pad * 3 - size}>Reversi</Title>
          {tally}
          <div className="flex-1" />
          {statusBlock}
          <div className="flex-1" />
          <div className={`space-y-[${ui.gap}px]`}>{buttons}</div>
        </div>
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {ui.H > ui.W * 1.3 ? <span className={`w-full text-[${ui.title}px] font-bold leading-tight`}>Reversi</span> : null}
      <div className={`flex items-center justify-between w-full h-[${ui.button}px]`}>
        {statusBlock}
        {tally}
      </div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex w-full gap-[${ui.gap}px]`}>{buttons}</div>
    </div>
  )
}

